/**
 * `netlab serve`: serve the static UI on a loopback HTTP port.
 *
 * The UI is a static build of `packages/web` (SvelteKit with the static
 * adapter), so there is no backend and no WebSocket: every request is a file
 * lookup. Two sources are possible.
 *
 * - Embedded: `manifest.gen.ts` (generated by `scripts/gen-manifest.ts`) imports
 *   every asset with `{ type: "file" }`, so `bun build --compile` packs the UI
 *   into the binary and `netlab` needs no installation. It wins when present.
 * - Disk: `packages/web/build` for development, with a clear error when neither
 *   source exists.
 *
 * Routing mirrors what the static build emits: the adapter writes flat files
 * (`practica.html`, not `practica/index.html`) while the app links to
 * `/practica`, so a pathname is tried verbatim, then with `.html`, then as a
 * directory index, and finally as the SPA shell. Assets keep a 404 so a missing
 * chunk does not answer with HTML.
 *
 * Usage: netlab serve [--port N] [--host H]
 * Exit codes: 0 when the server is stopped · 1 when the UI cannot be served ·
 * 2 on usage errors.
 */

import { statSync } from "node:fs";
import { join, resolve } from "node:path";

export const DEFAULT_SERVE_HOST = "127.0.0.1";
export const DEFAULT_SERVE_PORT = 8080;

export const SERVE_USAGE =
  "Usage: netlab serve [--port N] [--host H]\n" +
  "  serve the bundled UI over HTTP (loopback by default: no network exposure)\n" +
  "  --port N listens on N; 0 lets the OS pick a free port (default 8080)\n" +
  "  --host H binds H (default 127.0.0.1); pass 0.0.0.0 only on purpose\n" +
  '  prints "netlab listo en <url>" once the port is bound, before the first request\n' +
  "  exit 0 when stopped, 1 when no UI can be served, 2 on usage errors\n";

/** A file the fetch handler can answer with. */
export interface AssetInfo {
  /** Pathname the asset is registered under, e.g. `/practica.html`. */
  pathname: string;
  /** Where the bytes live: a disk path or an embedded `~BUN` path. */
  path: string;
  /** Byte length, reported on HEAD. */
  size: number;
}

/** Asset table the fetch handler resolves pathnames against. */
export interface UiRoutes {
  get(pathname: string): AssetInfo | null;
}

export interface ServeArgs {
  host: string;
  port: number;
}

/** Request handler shape `Bun.serve` accepts. */
export type FetchHandler = (request: Request) => Response;

const MIME_TYPES: Record<string, string> = {
  css: "text/css; charset=utf-8",
  gif: "image/gif",
  htm: "text/html; charset=utf-8",
  html: "text/html; charset=utf-8",
  ico: "image/x-icon",
  jpeg: "image/jpeg",
  jpg: "image/jpeg",
  js: "text/javascript; charset=utf-8",
  json: "application/json; charset=utf-8",
  map: "application/json; charset=utf-8",
  mjs: "text/javascript; charset=utf-8",
  png: "image/png",
  svg: "image/svg+xml",
  ttf: "font/ttf",
  txt: "text/plain; charset=utf-8",
  wasm: "application/wasm",
  webmanifest: "application/manifest+json; charset=utf-8",
  webp: "image/webp",
  woff: "font/woff",
  woff2: "font/woff2",
};

const DEFAULT_MIME = "application/octet-stream";

let cachedManifest: ReadonlyMap<string, string> | null | undefined;

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function usageError(message: string): Error {
  return new Error(`${message}\n${SERVE_USAGE}`);
}

function textResponse(
  status: number,
  body: string,
  headers: Record<string, string> = {},
): Response {
  return new Response(body, {
    status,
    headers: { "content-type": "text/plain; charset=utf-8", ...headers },
  });
}

/** Content type for an asset pathname, by extension. */
export function mimeTypeFor(pathname: string): string {
  const dot = pathname.lastIndexOf(".");
  if (dot <= pathname.lastIndexOf("/")) {
    return DEFAULT_MIME;
  }
  return MIME_TYPES[pathname.slice(dot + 1).toLowerCase()] ?? DEFAULT_MIME;
}

/** Whether the last segment looks like a page a browser navigates to (SPA). */
function isNavigation(pathname: string): boolean {
  const segment = pathname.slice(pathname.lastIndexOf("/") + 1);
  return segment === "" || !segment.includes(".");
}

/**
 * Pathnames to try, in order: the request itself, `+ ".html"`, `+ "/index.html"`
 * (the static adapter's directory index) and the SPA shell. A pathname with an
 * extension stops before the shell so a missing chunk stays a 404.
 */
export function routeCandidates(pathname: string): Array<string> {
  const trimmed = pathname === "/" ? "/" : pathname.replace(/\/+$/, "") || "/";
  const candidates: Array<string> = [pathname];
  if (trimmed !== pathname) {
    candidates.push(trimmed);
  }
  if (trimmed !== "/") {
    candidates.push(`${trimmed}.html`, `${trimmed}/index.html`);
  }
  if (isNavigation(pathname)) {
    candidates.push("/index.html");
  }
  return candidates.filter(
    (candidate, index) => candidates.indexOf(candidate) === index,
  );
}

/** Whether a pathname decodes to something that could escape the UI root. */
function isUnsafePath(pathname: string): boolean {
  let decoded: string;
  try {
    decoded = decodeURIComponent(pathname);
  } catch {
    return true;
  }
  if (decoded.includes("\0") || decoded.includes("\\")) {
    return true;
  }
  return decoded.split("/").some((segment) => segment === "..");
}

/** Routes over the assets embedded by `manifest.gen.ts` (real paths in dev). */
export function embeddedRoutes(assets: ReadonlyMap<string, string>): UiRoutes {
  return {
    get(pathname) {
      const path = assets.get(pathname);
      if (path === undefined) {
        return null;
      }
      return { pathname, path, size: Bun.file(path).size };
    },
  };
}

/** Routes over a UI build directory, for development and for a plain checkout. */
export function diskRoutes(root: string): UiRoutes {
  const base = resolve(root);
  return {
    get(pathname) {
      // `pathname` always starts with "/" and never contains "..": the handler
      // rejects traversal before it reaches this table.
      const path = join(base, pathname);
      const info = statSync(path, { throwIfNoEntry: false });
      if (info === undefined || !info.isFile()) {
        return null;
      }
      return { pathname, path, size: info.size };
    },
  };
}

/** Pick the embedded bundle when it exists, otherwise the build directory. */
export function routesFor(
  assets: ReadonlyMap<string, string> | null,
  buildDir: string,
): UiRoutes {
  if (assets !== null && assets.size > 0) {
    return embeddedRoutes(assets);
  }
  const shell = join(buildDir, "index.html");
  if (statSync(shell, { throwIfNoEntry: false }) === undefined) {
    throw new Error(
      `no UI bundle to serve: no embedded manifest and ${shell} is missing\n` +
        '  build the UI with "bun run --filter @netlab/web build" or regenerate the manifest with "bun run --filter @netlab/cli gen-manifest"',
    );
  }
  return diskRoutes(buildDir);
}

/**
 * Where the UI build lives in a checkout. Inside a compiled binary this points
 * into the `~BUN` root, which has no build directory: the embedded manifest is
 * what answers there.
 */
export function uiBuildDir(): string {
  return resolve(import.meta.dir, "../../web/build");
}

/**
 * Load the generated manifest, or `null` when it was never generated.
 *
 * The specifier has to be a literal so `bun build --compile` packs every asset
 * it imports; `manifest.gen.ts` is generated, so a fresh clone has no such
 * module and the disk fallback takes over.
 */
export async function loadEmbeddedManifest(): Promise<ReadonlyMap<
  string,
  string
> | null> {
  if (cachedManifest !== undefined) {
    return cachedManifest;
  }
  try {
    // biome-ignore lint/suspicious/noTsIgnore: manifest.gen.ts is generated at build time and a fresh clone has none
    // @ts-ignore -- same reason: the module is resolved by the bundler, not by tsc
    const module = (await import("./manifest.gen")) as {
      manifestAssets?: ReadonlyMap<string, string>;
    };
    cachedManifest = module.manifestAssets ?? null;
  } catch {
    cachedManifest = null;
  }
  return cachedManifest;
}

/** Build the `Bun.serve` fetch handler for a route table. */
export function createFetchHandler(routes: UiRoutes): FetchHandler {
  return (request) => {
    if (request.method !== "GET" && request.method !== "HEAD") {
      return textResponse(405, "method not allowed", { allow: "GET, HEAD" });
    }
    const { pathname } = new URL(request.url);
    if (isUnsafePath(pathname)) {
      return textResponse(404, "not found");
    }
    let asset: AssetInfo | null = null;
    for (const candidate of routeCandidates(pathname)) {
      asset = routes.get(candidate);
      if (asset !== null) {
        break;
      }
    }
    if (asset === null) {
      return textResponse(404, "not found");
    }
    const headers = { "content-type": mimeTypeFor(asset.pathname) };
    if (request.method === "HEAD") {
      return new Response(null, {
        status: 200,
        headers: { ...headers, "content-length": String(asset.size) },
      });
    }
    return new Response(Bun.file(asset.path), { status: 200, headers });
  };
}

/** Parse `netlab serve` arguments (without the command word). */
export function parseServeArgs(argv: Array<string>): ServeArgs {
  if (argv[0] === "-h" || argv[0] === "--help") {
    throw Object.assign(usageError("netlab serve serves the bundled UI."), {
      code: "HELP",
    });
  }
  let host = DEFAULT_SERVE_HOST;
  let port = DEFAULT_SERVE_PORT;
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i] as string;
    if (arg === "--port") {
      const raw = argv[++i];
      if (raw === undefined || !/^\d+$/.test(raw)) {
        throw usageError(
          `--port needs a port number, got ${JSON.stringify(raw)}`,
        );
      }
      port = Number.parseInt(raw, 10);
      if (port > 65535) {
        throw usageError(`--port must be between 0 and 65535, got ${port}`);
      }
    } else if (arg === "--host") {
      const raw = argv[++i];
      if (raw === undefined || raw.length === 0) {
        throw usageError("--host needs a host name or address");
      }
      host = raw;
    } else {
      throw usageError(`unknown flag ${JSON.stringify(arg)}`);
    }
  }
  return { host, port };
}

/**
 * `netlab serve` entrypoint.
 *
 * The URL is written to stdout as soon as `Bun.serve` returns and before the
 * event loop is given a chance to run, so the line always precedes the first
 * response; a caller can wait for it instead of polling the port.
 */
export async function runServe(argv: Array<string>): Promise<number> {
  let args: ServeArgs;
  try {
    args = parseServeArgs(argv);
  } catch (error) {
    const err = error as Error & { code?: string };
    if (err.code === "HELP") {
      process.stdout.write(SERVE_USAGE);
      return 0;
    }
    process.stderr.write(err.message);
    return 2;
  }

  let routes: UiRoutes;
  try {
    routes = routesFor(await loadEmbeddedManifest(), uiBuildDir());
  } catch (error) {
    process.stderr.write(`${errorMessage(error)}\n`);
    return 1;
  }

  const server = Bun.serve({
    hostname: args.host,
    port: args.port,
    fetch: createFetchHandler(routes),
    error(error) {
      process.stderr.write(`netlab serve: ${errorMessage(error)}\n`);
      return textResponse(500, "internal error");
    },
  });
  process.stdout.write(
    `netlab listo en http://${server.hostname}:${server.port}/\n`,
  );

  // Keep `main` pending: returning would exit the process and drop the server.
  // Ctrl-C ends the run.
  await new Promise<never>(() => {
    // never settles
  });
  return 0;
}
